# Torah (Pentateuch) + Esther book24_name values — the only books where
# targeted scroll-difference notes (מ:הערה-2) may appear in plus.
_NOTE_BOOKS = frozenset(
    [
        "ספר בראשית",
        "ספר שמות",
        "ספר ויקרא",
        "ספר במדבר",
        "ספר דברים",
        "מגילת אסתר",
    ]
)

# Normalize straight double-quote (U+0022) → Hebrew gershayim (U+05F4).
# The plus corpus JSON stores sug= values with straight quotes; claim data uses
# gershayim.  Normalizing both sides ensures they compare equal.
_NORM_QUOTES = str.maketrans({'"': "״"})


def verify_mp_plus_file_naming_book24_prefixes(
    record: ClaimRecord, ctx: Context
) -> None:
    """Observed plus file-name prefixes match the declared set exactly."""
    del ctx  # This check reads file names directly.
    declared = frozenset(record.data["prefixes"])

    plus_paths = glob.glob(str(paths.mam_parsed_dir() / "plus" / "*.json"))
    assert plus_paths, "no plus JSON files found for file-naming verification"

    def _prefixes(paths: list[str]) -> frozenset[str]:
        result = set()
        for p in paths:
            stem = Path(p).stem
            prefix = stem.split("-", 1)[0]
            result.add(prefix)
        return frozenset(result)

    plus_prefixes = _prefixes(plus_paths)
    assert plus_prefixes == declared, (
        f"plus filename prefixes {sorted(plus_prefixes)}"
        f" != declared {sorted(declared)}"
    )


def _verify_template_set_observed(
    record: ClaimRecord, ctx: Context, *, key: str = "templates"
) -> None:
    """Assert that every declared template appears in the plus corpus.

    key: the record.data key holding the name(s). If the value is a list,
    every element is checked. If it is a string (e.g. key="template"), it is
    wrapped in a list first.

    The reverse direction (observed subset of declared) is covered by
    verify_mp_plus_templates_all_groups_cover_all_observed.
    """
    declared_raw = record.data[key]
    if isinstance(declared_raw, list):
        declared = frozenset(declared_raw)
    else:
        declared = frozenset([declared_raw])
    missing = declared - ctx.template_names
    assert (
        not missing
    ), f"declared templates not found in plus corpus: {sorted(missing)}"


